import{_ as t,c as a,o,ag as s}from"./chunks/framework.dvv-DFtf.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),r={name:"getting-started.md"};function i(n,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide will help you install Kubby and connect to your first Kubernetes cluster.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before using Kubby, ensure you have:</p><ul><li><strong>kubectl</strong> installed and configured on your system</li><li>At least one Kubernetes cluster configured in your <code>~/.kube/config</code></li><li>macOS 11 (Big Sur) or later</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h3><p>Download the latest release from the <a href="https://github.com/adobe/kubby/releases" target="_blank" rel="noreferrer">GitHub Releases</a> page.</p><ol><li>Download the <code>.dmg</code> file for your Mac</li><li>Open the DMG and drag Kubby to your Applications folder</li><li>Launch Kubby from Applications</li></ol><div class="tip custom-block"><p class="custom-block-title">First Launch on macOS</p><p>On first launch, you may need to right-click the app and select &quot;Open&quot; to bypass Gatekeeper, since the app is not notarized.</p></div><h2 id="initial-setup" tabindex="-1">Initial Setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial Setup&quot;">​</a></h2><p>When you first launch Kubby, it will attempt to automatically detect your kubectl configuration and read all the contexts. Then for each of the contexts Kubby will also try to fetch the namespaces. This may fail if you do not have sufficient access rights, however you can still save a config file and edit it later.</p><h2 id="your-first-steps" tabindex="-1">Your First Steps <a class="header-anchor" href="#your-first-steps" aria-label="Permalink to &quot;Your First Steps&quot;">​</a></h2><p>Once connected, you&#39;ll see the <strong>Dashboard</strong> view showing a list of all clusters (contexts) and namespaces. Kubby is optimized for managing a large number of clusters, on the Dashboard it shows a searchable list of clusters and namespaces.</p><h3 id="try-these-actions" tabindex="-1">Try These Actions <a class="header-anchor" href="#try-these-actions" aria-label="Permalink to &quot;Try These Actions&quot;">​</a></h3><ol><li><strong>Navigate the Dashboard</strong>: Use <code>Tab</code> to move between resource tables, arrow keys to select items.</li><li><strong>View Deployments</strong>: Press <code>Enter</code> to see the deployments for a specific context and namespace.</li><li><strong>View Pods</strong>: Press <code>Enter</code> again on a deployment to see the pods for that deployment.</li><li><strong>Check Logs</strong>: Select a pod and press <code>L</code> to view logs from all containers in that pod.</li><li><strong>Describe a Resource</strong>: Press <code>D</code> on any resource to see detailed information.</li></ol><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Learn about all <a href="/features/">Features</a></li><li>Master the <a href="/shortcuts.html">Keyboard Shortcuts</a></li><li>Understand <a href="/navigation.html">Navigation</a> patterns</li></ul>',18)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
